contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool correct) public payable {
        require(c.baseToken() == address(0));
        require(c.initialized());
        require(address(this).balance >= amount);
        require(amount <= 1 ether);

        uint256 beforeBalance = address(c).balance;
        uint256 providedValue = correct ? amount : amount + 1;

        require(address(this).balance >= providedValue);

        bool reverted;
        try c.deposit{value: providedValue}(new uint256[](0), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(correct ? (!reverted && address(c).balance == beforeBalance + amount) : reverted);
    }

    receive() external payable {}
}

