contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount) public payable {
        require(address(this).balance >= 0, "balance check");

        (uint256 vBaseBefore, uint256 vNftBefore) = getReserves();

        bool reverted;
        try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 vBaseAfter, uint256 vNftAfter) = getReserves();

        assert(
            (reverted && vBaseAfter == vBaseBefore && vNftAfter == vNftBefore) ||
            (!reverted && vBaseAfter == vBaseBefore && vNftAfter == vNftBefore)
        );
    }

    function getReserves() internal view returns (uint256, uint256) {
        return (c.virtualBaseTokenReserves(), c.virtualNftReserves());
    }

    receive() external payable {}
}

